def calculate_busy_period_length(task_i, all_tasks, B_i, J_j):
    # This is a fixed-point iteration, simplified for intuition
    w_current = task_i.C + B_i
    while True:
        interference = 0
        for hp_task in get_priority_sets(task_i, all_tasks).hp_i:
