def calculate_occupied_period_length(task_i, all_tasks, B_i, F_i, J_j):
    # This is a fixed-point iteration, similar to busy period but with F_i considerations
    v_current = task_i.C - task_i.F + B_i
    while True:
        interference = 0
        for hp_task in get_priority_sets(task_i, all_tasks).hp_i:
