def calculate_R_i_preemptive_constrained(task_i, all_tasks):
    w_i_current = task_i.C + task_i.B
    while True:
        interference = 0
        for task_j in get_priority_sets(task_i, all_tasks).hp_i:
            interference += math.ceil((w_i_current + task_j.J) / task_j.T) * task_j.C
        w_i_next = task_i.C + task_i.B + interference
        if w_i_next == w_i_current:
            return w_i_next
        if w_i_next > task_i.D - task_i.J: # Check for unschedulability early
            return float('inf')
        w_i_current = w_i_next

def calculate_R_i_cooperative(task_i, all_tasks):
    # Step 1: Calculate w_i for Q_i
    w_i_current_Q = task_i.B
    while True:
        interference_Q = 0
        for task_j in get_priority_sets(task_i, all_tasks).hep_i:
            interference_Q += math.ceil((w_i_current_Q + task_j.J) / task_j.T) * task_j.C
        w_i_next_Q = task_i.B + interference_Q
        if w_i_next_Q == w_i_current_Q:
            break
        w_i_current_Q = w_i_next_Q
    Q_i = math.ceil((w_i_current_Q + task_i.J) / task_i.T)

    max_R_i = 0
    for q in range(Q_i):
        # Step 2: Calculate V_i_q
        V_i_q_current = task_i.B + q * task_i.F + task_i.C
        while True:
            interference_V = 0
            for task_j in get_priority_sets(task_i, all_tasks).hp_i:
                interference_V += math.ceil((V_i_q_current + task_j.J) / task_j.T) * task_j.C
            V_i_q_next = task_i.B + q * task_i.F + task_i.C + interference_V
            if V_i_q_next == V_i_q_current:
                break
            if V_i_q_next + task_i.F - q * task_i.T > task_i.D - task_i.J: # Check for unschedulability
                return float('inf')
            V_i_q_current = V_i_q_next

        R_i_q = V_i_q_current + task_i.F - q * task_i.T
        max_R_i = max(max_R_i, R_i_q)
    return max_R_i

def calculate_interference_upper_bound_single_task(task_j, t):
    U_j = task_j.C / task_j.T
    return U_j * t + task_j.C - U_j * (task_j.T - task_j.J)

def calculate_total_hp_interference_upper_bound(task_i, all_tasks, t):
    total_interference_UB = 0
    for task_j in get_priority_sets(task_i, all_tasks).hp_i:
        total_interference_UB += calculate_interference_upper_bound_single_task(task_j, t)
    return total_interference_UB

def get_max_R_i_UB_preemptive(task_i, all_tasks):
    # Due to monotonicity, only need to calculate for q=0
    # This function would call the calculation for R_i_q_UB with q=0
    return calculate_R_i_q_UB_preemptive(task_i, all_tasks, q=0)

def get_max_R_i_UB_cooperative(task_i, all_tasks):
    # Due to monotonicity, only need to calculate for q=0
    # This function would call the calculation for R_i_q_UB with q=0
    return calculate_R_i_q_UB_cooperative(task_i, all_tasks, q=0)

def sufficient_schedulability_test(all_tasks):
    # Sort tasks by priority (highest first)
    sorted_tasks = sorted(all_tasks, key=lambda t: t.priority, reverse=True)

    for task_i in sorted_tasks:
        R_i_UB = calculate_R_i_UB_cooperative(task_i, all_tasks) # Use the general formula
        if R_i_UB > (task_i.D - task_i.J):
            print(f"Task {task_i.id} is NOT schedulable by sufficient test (R_i_UB={R_i_UB} > D_i-J_i={task_i.D - task_i.J})")
            return False # System is not guaranteed schedulable by this test
    print("System is schedulable by sufficient test!")
    return True
